  "cl_title": "Reach à l'hôpital, à l'école, en salle de thérapie",
  "cl_lede": "La musique réduit l'anxiété et la douleur : 81 essais, 5,576 personnes atteintes de cancer (Cochrane 2021). Mais une « playlist calme » générique, c'est de la musique que le patient n'aime pas, alors on l'éteint. Reach construit la séance fondée sur les preuves à partir de la musique que chacun aime déjà.",
  "cl_p_tag": "Le problème",
  "cl_p_h": "La musique générique, on l'éteint",
  "cl_p_t": "Les équipes soignantes donnent à tout le monde la même playlist de relaxation. Une fillette autiste de 7 ans, une veuve de 72 ans à Madrid et un homme sourd qui ne dort pas ne réagissent pas au même morceau, et personne ne vérifie si ça a aidé.",
  "cl_s_tag": "Ce qui est nouveau",
  "cl_s_h": "Le goût devient le vecteur du remède",
  "cl_s_t": "Qloo lit ce que chaque personne aime en musique, cinéma, séries et livres, et choisit les artistes, les instruments et la texture qui sauront la captiver. Un conseil d'agents enveloppe ces goûts autour d'un protocole gradué (calme, sommeil, concentration, sans surcharge sensorielle, énergie), vérifie les règles de sécurité et scelle chaque décision pour qu'elle puisse être auditée.",
  "cl_u_tag": "En pratique",
  "cl_u_h": "Une infirmière, un parent, un patient",
  "cl_u_t": "Une infirmière ouvre le dossier d'un patient ; Reach compose en quelques secondes et joue sur n'importe quel téléphone ou tablette du service. Le patient dit si ça a aidé, et la séance suivante en tient compte. Les patients sourds ont une lumière qui respire et des vibrations. Une pièce pleine de monde reçoit une seule séance, juste pour chacun.",
  "cl_pat_h": "Patients",
  "cl_pat_t": "Chaque personne avec ses propres mots, sa dernière séance, et si elle a aidé. Ouvres-en une pour lancer sa séance dans le Studio.",
  "cl_cmp_h": "Pourquoi le goût compte, mesuré",
  "cl_cmp_t": "Une playlist calme générique (ce que n'importe quel modèle donne à tout le monde) face aux artistes que Qloo a choisis pour cette personne, les deux notés selon l'affinité Qloo avec elle. Ouvre d'abord un patient.",
  "cl_proof_h": "La preuve que rien n'a été modifié",
  "cl_proof_t": "Chaque étape de la décision est chaînée en SHA-256. Vérifie-la, puis modifie une étape et regarde la chaîne se rompre.",
