  "lab_delta": "Tiefschlafrhythmus (0.5–4 Hz). Musik bei Schlaflosigkeit: Grad A für den subjektiv erlebten Schlaf (Cochrane 2022); Delta-Entrainment durch Audio: Grad D.",
