  "cl_title": "Reach im Krankenhaus, in der Schule, im Therapieraum",
  "cl_lede": "Musik senkt Angst und Schmerz: 81 Studien, 5,576 Menschen mit Krebs (Cochrane 2021). Aber eine generische „Ruhe-Playlist“ ist Musik, die der Patient nicht liebt, also wird sie ausgeschaltet. Reach baut die evidenzbasierte Sitzung aus der Musik, die jede Person schon liebt.",
  "cl_p_tag": "Das Problem",
  "cl_p_h": "Standardmusik wird ausgeschaltet",
  "cl_p_t": "Pflegeteams geben allen dieselbe Entspannungsplaylist. Ein 7-jähriges autistisches Mädchen, eine 72-jährige Witwe in Madrid und ein gehörloser Mann, der nicht schlafen kann, reagieren nicht auf denselben Titel, und niemand prüft, ob es geholfen hat.",
  "cl_s_tag": "Was neu ist",
  "cl_s_h": "Geschmack wird zum Träger der Medizin",
  "cl_s_t": "Qloo liest, was jede Person in Musik, Film, TV und Büchern liebt, und wählt die Künstler, Instrumente und Klangtextur, die sie fesseln. Ein Rat aus Agenten legt diesen Geschmack um ein bewertetes Protokoll (Ruhe, Schlaf, Fokus, reizarm, Energie), prüft Sicherheitsregeln und versiegelt jede Entscheidung, damit sie überprüft werden kann.",
  "cl_u_tag": "Im echten Einsatz",
  "cl_u_h": "Eine Pflegekraft, ein Elternteil, ein Patient",
  "cl_u_t": "Eine Pflegekraft öffnet einen Patienten; Reach komponiert in Sekunden und spielt auf jedem Handy oder Stations-Tablet. Der Patient sagt, ob es geholfen hat, und die nächste Sitzung lernt daraus. Gehörlose Patienten bekommen ein atmendes Licht und Vibration. Ein Raum voller Menschen bekommt eine Sitzung, die für alle fair ist.",
  "cl_pat_h": "Patienten",
  "cl_pat_t": "Jede Person in ihren eigenen Worten, ihre letzte Sitzung und ob sie geholfen hat. Öffne eine, um ihre Sitzung im Studio zu starten.",
  "cl_cmp_h": "Warum Geschmack zählt, gemessen",
  "cl_cmp_t": "Eine Standard-Ruhe-Playlist (was jedes Modell allen gibt) gegen die Künstler, die Qloo für diese Person gewählt hat, beide nach Qloos Affinität zur Person bewertet. Öffne zuerst einen Patienten.",
  "cl_proof_h": "Beweis, dass nichts verändert wurde",
  "cl_proof_t": "Jeder Schritt der Entscheidung ist mit SHA-256 verkettet. Prüf ihn, dann ändere einen Schritt und sieh zu, wie die Kette bricht.",
  "cl_details": "technische Details",
  "cl_ev_h": "Die Evidenz hinter jeder Sitzung",
  "cl_ev_t": "Bewertet von A (stark) bis D (experimentell), mit der Studie hinter jeder Aussage.",
