  "u_music_d": "Sag, wen du liebst. Qloos Geschmacksgraph findet die Künstler, die ihnen nahestehen, in deiner eigenen Kultur, und ein Protokoll mit bewerteter Evidenz legt Tempo, Puls und eine sichere Lautstärke fest.",
