  "u_freq_s": "Spiel die Klangplatte",
  "u_freq_d": "Fünf Gehirnwellenbänder, jedes zeichnet seine eigene Figur in Sand. Wähl ein Band, eine tiefe oder hohe Tonlage, Lautsprecher oder Kopfhörer, und hör zu. Entrainment ist experimentell und auch so gekennzeichnet.",
