  "u_hands_t": "Eine Hand",
  "u_hands_s": "Gesten",
  "u_hands_d": "Zwei Finger für den nächsten Song, eine offene Hand für Play oder Pause, Daumen hoch zum Merken, Daumen runter für „nicht der hier“. Für wenn du liegst und das Handy weit weg ist.",
