  "cl_title": "Reach in ospedale, a scuola, in una stanza di terapia",
  "cl_lede": "La musica riduce ansia e dolore: 81 studi, 5,576 persone con cancro (Cochrane 2021). Ma una “playlist rilassante” generica è musica che il paziente non ama, quindi viene spenta. Reach costruisce la sessione basata sulle evidenze con la musica che ogni persona già ama.",
  "cl_p_tag": "Il problema",
  "cl_p_h": "La musica generica viene spenta",
  "cl_p_t": "I team di cura danno a tutti la stessa playlist di rilassamento. Una bambina autistica di 7 anni, una vedova di 72 anni a Madrid e un uomo sordo che non riesce a dormire non reagiscono allo stesso brano, e nessuno controlla se ha aiutato.",
  "cl_s_tag": "Cosa c'è di nuovo",
  "cl_s_h": "Il gusto diventa il veicolo della medicina",
  "cl_s_t": "Qloo legge cosa ama ogni persona tra musica, cinema, TV e libri, e sceglie gli artisti, gli strumenti e la trama sonora capaci di coinvolgerla. Un consiglio di agenti avvolge quel gusto attorno a un protocollo graduato (calma, sonno, concentrazione, sicurezza sensoriale, energia), controlla le regole di sicurezza e sigilla ogni decisione perché possa essere verificata.",
  "cl_u_tag": "Nell'uso reale",
  "cl_u_h": "Un'infermiera, un genitore, un paziente",
  "cl_u_t": "Un'infermiera apre un paziente; Reach compone in pochi secondi e suona su qualsiasi telefono o tablet di reparto. Il paziente dice se ha aiutato, e la sessione successiva impara. I pazienti sordi ricevono una luce che respira e vibrazioni. Una stanza piena di persone riceve un'unica sessione equa per tutti.",
  "cl_pat_h": "Pazienti",
  "cl_pat_t": "Ogni persona con le sue parole, la sua ultima sessione e se ha aiutato. Aprine una per avviare la sua sessione nello Studio.",
  "cl_cmp_h": "Perché il gusto conta, misurato",
  "cl_cmp_t": "Una playlist rilassante generica (quella che qualsiasi modello dà a tutti) contro gli artisti che Qloo ha scelto per questa persona, entrambi valutati con l'affinità Qloo verso la persona. Apri prima un paziente.",
