  "cl_title": "Reach no hospital, na escola, na sala de terapia",
  "cl_lede": "A música reduz ansiedade e dor: 81 estudos, 5,576 pessoas com câncer (Cochrane 2021). Mas uma “playlist relaxante” genérica é música que o paciente não ama, então ela é desligada. O Reach monta a sessão baseada em evidências com a música que cada pessoa já ama.",
