  "cl_cmp_t": "Uma playlist relaxante genérica (o que qualquer modelo dá a todo mundo) contra os artistas que o Qloo escolheu para esta pessoa, ambos pontuados pela afinidade do Qloo com a pessoa. Abra um paciente primeiro.",
