  "cl_title": "Hastanede, okulda, terapi odasında Reach",
  "cl_lede": "Müzik kaygıyı ve ağrıyı azaltır: kanserli 5.576 kişiyle 81 çalışma (Cochrane 2021). Ama sıradan bir “sakinleştirici çalma listesi” hastanın sevmediği müziktir, bu yüzden kapatılır. Reach, kanıta dayalı seansı her kişinin zaten sevdiği müzikten kurar.",
  "cl_p_tag": "Sorun",
  "cl_p_h": "Sıradan müzik kapatılır",
  "cl_p_t": "Bakım ekipleri herkese aynı rahatlama listesini verir. 7 yaşında otizmli bir kız, Madrid'de 72 yaşında bir dul ve uyuyamayan işitme engelli bir adam aynı parçaya aynı tepkiyi vermez; üstelik kimse işe yarayıp yaramadığını kontrol etmez.",
