  "cl_s_t": "Qloo her kişinin müzikte, filmde, dizide ve kitapta neyi sevdiğini okur; onu tutacak sanatçıları, enstrümanları ve dokuyu seçer. Bir ajan konseyi bu zevki derecelendirilmiş bir protokolün (sakinlik, uyku, odak, duyusal açıdan güvenli, enerji) etrafına sarar, güvenlik kurallarını kontrol eder ve her kararı denetlenebilsin diye mühürler.",
  "cl_u_tag": "Gerçek kullanımda",
  "cl_u_h": "Bir hemşire, bir ebeveyn, bir hasta",
  "cl_u_t": "Hemşire bir hastayı açar; Reach saniyeler içinde besteler ve herhangi bir telefonda ya da servis tabletinde çalar. Hasta işe yarayıp yaramadığını söyler, sonraki seans bundan öğrenir. İşitme engelli hastalar nefes ışığı ve titreşim alır. Bir oda dolusu insan, herkese adil tek bir seans alır.",
  "cl_pat_h": "Hastalar",
  "cl_pat_t": "Her kişi kendi sözleriyle, son seansı ve işe yarayıp yaramadığı. Birini aç ve seansını Stüdyo'da çalıştır.",
