  "lab_alpha": "आरामदेह जागृति (8–12 Hz)। शांति और मूड के सेशन यहीं रहते हैं; तनाव और चिंता के लिए संगीत: ग्रेड A (104 RCT, d = 0.38–0.55)।",
  "lab_beta": "सतर्क एकाग्रता (12–30 Hz)। फ़ोकस रैंप थोड़े यादृच्छिक बदलाव के साथ 16 Hz तक चढ़ता है; बाइनॉरल बीट्स का संयुक्त g = 0.45, तंत्र अप्रमाणित।",
  "lab_gamma": "40 Hz सहायता। अल्ज़ाइमर रोग में परखा जा रहा है (OVERTURE, HOPE जारी): वहाँ ग्रेड C, वेलनेस के लिए D। ऑडियो पल्स, रोशनी की टिमटिमाहट (photic flicker) नहीं हैं।",
