  "cl_s_t": "Qloo पढ़ता है कि हर व्यक्ति को संगीत, फ़िल्म, टीवी और किताबों में क्या पसंद है, और वे कलाकार, वाद्य और बनावट चुनता है जो उन्हें थामे रखेंगे। एजेंटों की एक परिषद उस पसंद को ग्रेड वाले एक प्रोटोकॉल (शांति, नींद, फ़ोकस, संवेदी रूप से सुरक्षित, ऊर्जा) के इर्द-गिर्द लपेटती है, सुरक्षा नियम जाँचती है, और हर फ़ैसले को सील करती है ताकि उसका ऑडिट हो सके।",
  "cl_u_tag": "असल इस्तेमाल में",
  "cl_u_h": "एक नर्स, एक अभिभावक, एक मरीज़",
  "cl_u_t": "नर्स किसी मरीज़ को खोलती है; Reach कुछ ही सेकंड में रचना करता है और किसी भी फ़ोन या वार्ड टैबलेट पर बजाता है। मरीज़ बताता है कि मदद मिली या नहीं, और अगला सेशन उससे सीखता है। बधिर मरीज़ों को साँस की रोशनी और कंपन मिलता है। लोगों से भरे कमरे को एक ऐसा सेशन मिलता है जो सबके लिए निष्पक्ष हो।",
  "cl_pat_h": "मरीज़",
  "cl_pat_t": "हर व्यक्ति अपने शब्दों में, उनका पिछला सेशन, और क्या उससे मदद मिली। किसी को खोलकर उनका सेशन स्टूडियो में चलाएँ।",
  "cl_cmp_h": "पसंद क्यों मायने रखती है, नापकर देखा",
  "cl_cmp_t": "एक आम शांत प्लेलिस्ट (जो कोई भी मॉडल सबको थमा देता है) बनाम वे कलाकार जो Qloo ने इस व्यक्ति के लिए चुने; दोनों को व्यक्ति से Qloo के जुड़ाव के आधार पर आँका जाता है। पहले किसी मरीज़ को खोलें।",
