  "cl_title": "病院で、学校で、セラピールームで使う Reach",
  "cl_lede": "音楽は不安と痛みを和らげます:がんを抱える5,576人を対象とした81件の試験(Cochrane 2021)。でも、汎用の「リラックス用プレイリスト」は患者さんが好きではない音楽なので、止められてしまいます。Reach は、一人ひとりがすでに好きな音楽から、エビデンスに基づくセッションを組み立てます。",
