  "cl_p_h": "汎用の音楽は止められてしまう",
  "cl_p_t": "ケアチームは全員に同じリラクゼーション用プレイリストを渡します。自閉症の7歳の女の子、Madrid に住む72歳の未亡人、眠れない聴覚障害の男性が、同じ曲に同じように反応することはありません。そして、役立ったかどうかを誰も確かめません。",
  "cl_s_tag": "新しい点",
  "cl_s_h": "好みが、薬を運ぶ土台になる",
  "cl_s_t": "Qloo は、音楽、映画、テレビ、本にわたって一人ひとりが好きなものを読み取り、その人を惹きつけるアーティスト、楽器、質感を選びます。エージェントの評議会がその好みを等級づけされたプロトコル(落ち着き、睡眠、集中、感覚にやさしい、エネルギー)に組み込み、安全ルールを確認し、監査できるようにすべての判断を封印します。",
  "cl_u_tag": "実際の使い方",
  "cl_u_h": "看護師、保護者、患者",
  "cl_u_t": "看護師が患者を開くと、Reach は数秒で作曲し、どのスマホや病棟のタブレットでも再生します。患者さんが役立ったかどうかを伝え、次のセッションがそこから学びます。耳の聞こえない患者さんには、呼吸の光と振動を。大勢がいる部屋には、全員に公平な1つのセッションを。",
  "cl_pat_h": "患者",
